export type ParsedPurchaseListingInstruction<
  TProgram extends string = typeof KATHA_MARKETPLACE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    config: TAccountMetas[0];
    registryProgram: TAccountMetas[1];
    registryConfig: TAccountMetas[2];
    artwork: TAccountMetas[3];
    verification: TAccountMetas[4];
    conditionHead: TAccountMetas[5];
    conditionReport: TAccountMetas[6];
    custodyHead: TAccountMetas[7];
    saleTerms: TAccountMetas[8];
    asset: TAccountMetas[9];
    seller: TAccountMetas[10];
    listing: TAccountMetas[11];
    collection: TAccountMetas[12];
    coreProgram: TAccountMetas[13];
    buyer: TAccountMetas[14];
    paymentMint: TAccountMetas[15];
    tokenProgram: TAccountMetas[16];
    buyerTokens: TAccountMetas[17];
    sellerTokens: TAccountMetas[18];
    artistTokens: TAccountMetas[19];
    treasuryTokens: TAccountMetas[20];
    systemProgram: TAccountMetas[21];
    /** listings use their immutable initialization settings, even after fee updates. */
    listingFees: TAccountMetas[22];
  };
  data: PurchaseListingInstructionData;
};

export function parsePurchaseListingInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedPurchaseListingInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 23) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 23,
    });
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      config: getNextAccount(),
      registryProgram: getNextAccount(),
      registryConfig: getNextAccount(),
      artwork: getNextAccount(),
      verification: getNextAccount(),
      conditionHead: getNextAccount(),
      conditionReport: getNextAccount(),
      custodyHead: getNextAccount(),
      saleTerms: getNextAccount(),
      asset: getNextAccount(),
      seller: getNextAccount(),
      listing: getNextAccount(),
      collection: getNextAccount(),
      coreProgram: getNextAccount(),
      buyer: getNextAccount(),
      paymentMint: getNextAccount(),
      tokenProgram: getNextAccount(),
      buyerTokens: getNextAccount(),
      sellerTokens: getNextAccount(),
      artistTokens: getNextAccount(),
      treasuryTokens: getNextAccount(),
      systemProgram: getNextAccount(),
      listingFees: getNextAccount(),
    },
    data: getPurchaseListingInstructionDataDecoder().decode(instruction.data),
  };
}
